import pyomo.environ as pyo

DATA = {
    "initiatives": ["X", "Y"],
    "cost_per_unit": {"X": 20, "Y": 10},
    "total_resource_cap": 500,     # combined X + Y <= 500
    "min_diff_X_over_Y": 100,      # X - Y >= 100
    "max_X": 350,                  # X <= 350
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # --- Sets ---
    model.INIT = pyo.Set(initialize=d["initiatives"])

    # --- Variables ---
    def alloc_bounds(m, i):
        if i == "X":
            return (0, d["max_X"])
        return (0, None)

    model.alloc = pyo.Var(
        model.INIT,
        within=pyo.NonNegativeIntegers,
        bounds=alloc_bounds,
    )

    # --- Objective: minimize total cost ---
    def obj_rule(m):
        return sum(d["cost_per_unit"][i] * m.alloc[i] for i in m.INIT)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # --- Constraints ---
    # Combined resources cannot exceed the total cap.
    def total_cap_rule(m):
        return sum(m.alloc[i] for i in m.INIT) <= d["total_resource_cap"]

    model.total_cap = pyo.Constraint(rule=total_cap_rule)

    # X must receive at least 100 more units than Y.
    def min_diff_rule(m):
        return m.alloc["X"] - m.alloc["Y"] >= d["min_diff_X_over_Y"]

    model.min_diff = pyo.Constraint(rule=min_diff_rule)

    return model


